async function api(path,body,requestOptions={}){const opts={...requestOptions,headers:{Accept:'application/json'}};if(body){opts.method='POST';opts.headers['Content-Type']='application/json';opts.headers['X-CSRF-Token']=state.health.csrf_token||'';opts.body=JSON.stringify(body);}const description=path.startsWith('/communications')?'komunikatów':path.startsWith('/sources')?'stanu źródeł':path.startsWith('/ioda')?'danych łączności IODA':path.startsWith('/fires')?'wykryć satelitarnych':path.startsWith('/effis')?'prognozy EFFIS':path.startsWith('/ukraine')?'alertów Ukrainy NEPTUN':'stanu aplikacji';const {response,data:result}=await fetchJSON(`/api${path}`,opts,description);if(!response.ok){const detail=typeof result.detail==='string'?result.detail:JSON.stringify(result.detail||result);throw new Error(detail);}return result;}
function items(data){return Array.isArray(data)?data:(data.items||[]);}
