function sourceStatus(s){if(state.health.mode==='demo'&&s.access_state==='disabled_by_user')return 'disabled_in_demo';return s.access_state&&s.access_state!=='enabled'?s.access_state:s.status||s.state||s.last_result||'needs_verification';}
function sourceSummary(s){return `dostęp: ${label(sourceStatus(s))} / ostatnia próba: ${label(s.last_result||s.status||'unknown')}${sourceStale(s)?' / nieaktualne':''}${s.error?` / ${s.error}`:''}`;}
function sourceStale(s){if(s.stale!==undefined)return s.stale;const checked=s.last_successful_check||s.last_success_at||s.last_checked_at;if(!checked)return true;return(new Date(state.health.now)-new Date(checked))/1000>3*(s.interval_seconds||300)+120;}
async function loadSources(){state.sources=items(await api('/sources'));renderSources();renderFireStatus();const issues=state.sources.filter(s=>['error','blocked','partial','disabled','blocked_access','disabled_by_user','disabled_in_demo','needs_verification'].includes(sourceStatus(s))||['error','partial'].includes(s.last_result)||sourceStale(s)||s.coverage_complete===false);const c=$('coverage');c.classList.toggle('problem',issues.length>0);const coveragePanel=$('coverage-panel'),coverageSummary=$('coverage-summary');if(coveragePanel)coveragePanel.classList.toggle('problem',issues.length>0||Boolean(state.health.gap_seconds));if(coverageSummary)coverageSummary.textContent=(issues.length?`${issues.length} z ${state.sources.length} źródeł z ograniczeniami`:`${state.sources.length} źródeł · stan odczytu`)+(state.health.gap_seconds?' · przerwa w monitoringu':'');c.textContent=issues.length?`Ograniczenia źródeł: ${issues.map(s=>`${s.name||s.id}: ${sourceSummary(s)}`).join(' · ')}. Zapisane rekordy pozostają dostępne.`:`${state.sources.length} źródła · zakres wybranych publikacji, bez gwarancji pełnego obrazu sytuacji.`;if(state.health.gap_seconds)c.append(el('span',` Przerwa w pracy: ${Math.round(state.health.gap_seconds/60)} min; w tym czasie nie trwał monitoring.`));}
function filters(){const f=new FormData($('filters')),q=new URLSearchParams();for(const [k,v]of f)if(v)q.set(k,v);if(f.has('include_active'))q.set('include_active','true');return q.toString();}
