function imgwNotice(){const box=el('div',null,'muted');box.append(el('p','Źródłem pochodzenia danych jest Instytut Meteorologii i Gospodarki Wodnej – Państwowy Instytut Badawczy'),el('p','Dane Instytutu Meteorologii i Gospodarki Wodnej – Państwowego Instytutu Badawczego zostały przetworzone'));const a=el('a','Warunki i oznaczenia dostawców');a.href='/notices';box.append(a);return box;}
function renderSources(){const root=$('source-list');clear(root);for(const s of state.sources){const c=el('article',null,'source-card');c.append(badge(sourceStatus(s), ['error','blocked','blocked_access'].includes(sourceStatus(s))?'alert':''),el('h3',s.name||s.id));if(s.last_result)c.append(badge(s.last_result,['error','partial'].includes(s.last_result)?'alert':''));c.append(descriptionList([['Ostatnia próba',date(s.last_attempt_at||s.last_fetch_at)],['Dostęp',label(state.health.mode==='demo'&&s.access_state==='disabled_by_user'?'disabled_in_demo':s.access_state)],['Poprawny odczyt',date(s.last_successful_check||s.last_success_at||s.last_checked_at)],['Wynik',label(s.last_result||s.status)],['Świeżość',sourceStale(s)?'Nieaktualne':s.freshness||'Według ostatniego odczytu'],['Zakres',typeof s.coverage==='object'?JSON.stringify(s.coverage):s.coverage||s.scope||'Zakres nieustalony'],['Interwał',`${s.interval_seconds||s.interval||'—'} s`]]));if(s.error||s.last_error||s.access_note)c.append(el('p',s.error||s.last_error||s.access_note,'notice'));if(s.url)c.append(sourceLink(s.url,'Serwis instytucji'));if(s.id==='imgw_meteo')c.append(imgwNotice());if(s.id==='ioda'&&s.ioda)c.append(descriptionList([['Ostatni pomiar IODA',date(s.ioda.measurement_at)],['Wiek pomiaru',s.ioda.measurement_age_seconds==null?'Brak pomiarów':`${Math.floor(s.ioda.measurement_age_seconds/60)} min`],['Stan ostatniego zapisanego pomiaru',({available:'Dostępny',stale:'Nieaktualny',no_measurements:'Brak pomiarów'})[s.ioda.measurement_state]],['Pokrycie jednostka/sygnał',`${s.ioda.signal_coverage?.available||0} aktualnych · ${s.ioda.signal_coverage?.stale||0} nieaktualnych · ${s.ioda.signal_coverage?.no_measurements||0} bez pomiarów · ${s.ioda.signal_coverage?.read_error||0} błędów`],['Częściowe błędy IODA',(s.ioda.errors||[]).join('; ')||'Brak zapisanych błędów']]));const row=el('div',null,'form-actions');const b=el('button',s.access_state==='blocked_access'?'Ponów sprawdzenie dostępu':'Odśwież źródło');const cannotRefresh=()=>state.health.mode==='demo'||s.running||!['enabled','blocked_access','needs_verification'].includes(s.access_state||'enabled');b.disabled=cannotRefresh();b.addEventListener('click',async()=>{b.disabled=true;try{await api(`/sources/${encodeURIComponent(s.id)}/refresh`,{});$('global-status').textContent='Odświeżenie źródła zaplanowane. Stan zmieni się po zakończeniu próby.';}catch(err){error(err);}finally{b.disabled=cannotRefresh();}});row.append(b);c.append(row);root.append(c);}}
let mapReady=false;
// PRG cartography is presentation-only; warning/data colors stay owned by their sources.
function mapPresentationStyles(){
 const tokens=window.getComputedStyle?.(document.documentElement);
 const token=(name,fallback)=>tokens?.getPropertyValue(name).trim()||fallback;
 return {
  administrative:{color:token('--map-prg-line','#9babb6'),weight:1,fillColor:token('--map-prg-fill','#f7fafb')},
  borders:[{color:token('--map-border-halo','#ffffff'),weight:7,opacity:.95},{color:token('--map-border-line','#17465c'),weight:3,opacity:1}]
 };
}
function applyMapTheme(){
 if(!state.administrativeLayer&&!state.countryBorderLayers.length)return;
 const styles=mapPresentationStyles();
 // Deliberately omit fillOpacity: syncOsm owns whether the PRG base is opaque.
 state.administrativeLayer?.setStyle(styles.administrative);
 state.countryBorderLayers.forEach((layer,index)=>layer.setStyle(styles.borders[index]));
}
document.addEventListener('wici:themechange',applyMapTheme);
async function initMap(){if(mapReady){syncOsm();return;}if(!window.L){$('map-note').textContent='Nie udało się odczytać lokalnej biblioteki mapy. Lista pozostaje dostępna.';return;}if(!state.map){state.map=L.map('map',{zoomControl:true,attributionControl:true}).setView([52.05,19.2],6);window.WiciAtlas?.setMap(state.map);state.map.attributionControl.addAttribution('Granice: PRG / GUGiK');state.map.createPane('osmBase').style.zIndex='150';state.map.createPane('administrativeBase').style.zIndex='200';state.map.createPane('effisForecast').style.zIndex='350';state.map.createPane('trafficFlow').style.zIndex='390';state.map.createPane('countryBorder').style.zIndex='410';state.map.getPane('countryBorder').style.pointerEvents='none';state.map.on('click',lookupTrafficRoad);state.map.createPane('fireDetections').style.zIndex='450';state.map.createPane('gddkiaIncidents').style.zIndex='470';}syncOsm();try{const results=await Promise.all(['provinces','counties','poland-border'].map(async name=>{const {response,data}=await fetchJSON(`/static/geo/${name}.geojson`,{},'lokalnych granic mapy');if(!response.ok)throw new Error('Brak lokalnych granic PRG');return data;}));for(const collection of results.slice(0,2))for(const f of collection.features||[])state.geometries.set(String(f.properties.admin_code||f.id),f);state.geometries.set('PL',results[2]);const provinces=results[0],mapStyles=mapPresentationStyles();state.administrativeLayer=L.geoJSON(provinces,{pane:'administrativeBase',style:{...mapStyles.administrative,fillOpacity:1},onEachFeature:(feature,layer)=>{layer.bindTooltip(el('span',feature.properties.name),{sticky:true});}}).addTo(state.map);for(const style of mapStyles.borders)state.countryBorderLayers.push(L.geoJSON(results[2],{pane:'countryBorder',interactive:false,style:{...style,fill:false,lineCap:'round',lineJoin:'round'}}).addTo(state.map));const options=provinces.features.map(f=>({code:f.properties.admin_code,name:f.properties.name})).sort((a,b)=>a.name.localeCompare(b.name,'pl'));for(const p of options){const o=el('option',p.name);o.value=p.code;$('province').append(o);}window.WiciRegion?.init({map:state.map,provinces,select:$('province'),country:results[2]});mapReady=true;syncOsm();renderMap();syncIoda();}catch(err){$('map-note').textContent='Brak geometrii referencyjnej. Publikacje są dostępne na liście; aplikacja nie tworzy zastępczych punktów. Wybierz „Odśwież widok”, aby ponowić odczyt granic.';throw err;}}
function geometryFor(loc){return state.geometries.get(String(loc.geometry_ref||loc.admin_code));}
function renderMap(){if(!state.map)return;for(const card of state.cards)state.map.removeLayer(card);state.cards=[];for(const obj of state.layers)state.map.removeLayer(obj.layer);state.layers=[];const groups=new Map();for(const event of state.communications)for(const loc of locations(event)){const geo=geometryFor(loc);if(!geo)continue;const key=JSON.stringify([loc.role,loc.geometry_ref||loc.admin_code||geo]);if(!groups.has(key))groups.set(key,{geo,role:loc.role,name:loc.name,events:[]});const g=groups.get(key);if(!g.events.some(e=>e.id===event.id))g.events.push(event);}for(const g of groups.values()){const inactive=g.events.every(e=>e.source_id==='imgw_meteo'&&['cancelled','expired'].includes(e.warning_status));const levels=g.events.filter(e=>!['cancelled','expired'].includes(e.warning_status)).map(e=>Number(e.official_severity)).filter(n=>n>=1&&n<=3);const severity=levels.length?Math.max(...levels):0;const tone=inactive?'#82909b':severity===3?'#bf3232':severity===2?'#cf7717':severity===1?'#bba025':null;const style={color:tone||(g.role==='warning_area'?'#b36a23':g.role==='notification_area'?'#3f719a':'#16716a'),weight:2,fillColor:tone||(g.role==='warning_area'?'#e9ac64':g.role==='notification_area'?'#83b1d6':'#16716a'),fillOpacity:.25,dashArray:g.role==='notification_area'?'6 4':undefined};const layer=L.geoJSON(g.geo,{style,pointToLayer:(f,ll)=>L.circleMarker(ll,{...style,radius:7,fillOpacity:.8})});const popup=el('div',null,'map-popup');popup.append(el('strong',g.name),el('p',label(g.role)));for(const event of g.events){const b=el('button',event.title);b.addEventListener('click',()=>selectCommunication(event.id));popup.append(b);}layer.bindPopup(popup).addTo(state.map);state.layers.push({layer,events:g.events.map(e=>e.id),style});}renderProvinceCards();highlightMap(state.selected,false);syncCommunicationMapVisibility();renderFires();}
function communicationMapVisible(){
  return $('communications-enabled')?.checked!==false&&!($('ioda-enabled')?.checked&&!$('ioda-communications')?.checked);
}
function syncCommunicationMapVisibility(){
  const enabled=$('communications-enabled')?.checked!==false;
  const focused=Boolean($('ioda-enabled')?.checked&&!$('ioda-communications')?.checked);
  const visible=communicationMapVisible();
  if(state.map)for(const layer of [...state.layers.map(item=>item.layer),...state.cards]){
    if(!visible){if(state.map.hasLayer(layer))state.map.removeLayer(layer);}
    else if(!state.map.hasLayer(layer))layer.addTo(state.map);
  }
  for(const element of document.querySelectorAll('.communications-map-key'))element.hidden=!visible;
  if($('map-title'))$('map-title').textContent=focused?'Łączność internetowa':'Mapa sytuacji';
  if($('map-subtitle'))$('map-subtitle').textContent=focused?'Detekcje IODA w wybranym oknie':visible?'Komunikaty i warstwy danych':'Warstwy danych';
  if($('communications-status'))$('communications-status').textContent=!enabled?'Nakładka komunikatów wyłączona.':focused?'Nakładka ukryta w trybie IODA. Włącz „Pokaż też komunikaty i ostrzeżenia na mapie” w Łączności.':'Nakładka komunikatów włączona.';
  const note=$('ioda-map-context');
  if(note)note.textContent=!enabled?'Nakładka komunikatów wyłączona w Warstwach; lista publikacji jest dostępna.':focused?'Komunikaty ukryte na mapie; dostępne na liście.':'Wspólny widok: łączność i komunikaty źródeł.';
}
for(const id of ['communications-enabled','ioda-enabled','ioda-communications'])$(id)?.addEventListener('change',syncCommunicationMapVisibility);
syncCommunicationMapVisibility();
function highlightMap(id,pan=true){let bounds=null;for(const o of state.layers){const selected=o.events.includes(id);o.layer.setStyle({...o.style,weight:selected?4:2,fillOpacity:selected?.5:.25});if(selected){o.layer.bringToFront();const b=o.layer.getBounds();if(b.isValid())bounds=bounds?bounds.extend(b):b;}}if(pan&&bounds&&communicationMapVisible()){const panel=$('detail-panel');const drawerWidth=panel&&!panel.hidden?(panel.getBoundingClientRect?.().width||0):0;const mapWidth=state.map.getSize?.().x||0;const left=drawerWidth&&mapWidth-drawerWidth>220?drawerWidth+44:30;state.map.fitBounds(bounds,{paddingTopLeft:[left,90],paddingBottomRight:[30,45],maxZoom:9});}}
for(const tab of document.querySelectorAll('.tab'))tab.addEventListener('click',()=>{state.view=tab.dataset.view;for(const v of document.querySelectorAll('.view'))v.hidden=v.id!==state.view;for(const t of document.querySelectorAll('.tab')){const active=t===tab;t.classList.toggle('active',active);if(active)t.setAttribute('aria-current','page');else t.removeAttribute('aria-current');}if(state.view==='situation'&&state.map)setTimeout(()=>state.map.invalidateSize(),0);syncTraffic();syncGddkia();syncOsm();syncWeather();});
async function changeDay(value){window.WiciAtlas?.resetDetails();state.day=value;$('selected-day').value=value;syncIoda();$('include-active').checked=value===serverDay()&&(window.WiciPreferences?.value('include-active',state.health.mode==='demo')??(state.health.mode==='demo'));$('include-active').disabled=value!==serverDay();window.WiciAtlas?.updateFilterSummary();state.selected=null;$('details').replaceChildren(el('p','Wybierz publikację z wybranego dnia.','empty'));await Promise.all([loadCommunications(),loadFires()]);}
for(const [id,offset] of [['previous-day',-1],['next-day',1]])$(id).addEventListener('click',()=>{const d=new Date(`${$('selected-day').value}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+offset);const value=d.toISOString().slice(0,10);if(value<=serverDay())changeDay(value).catch(error);});
$('today').addEventListener('click',()=>changeDay(serverDay()).catch(error));
$('filters').addEventListener('change',e=>{if(e.target.id==='selected-day'){if(e.target.value&&e.target.value<=serverDay())changeDay(e.target.value).catch(error);return;}loadCommunications().catch(error);if(e.target.id==='province'){window.WiciRegion?.select(e.target.value);loadFires().catch(error);syncIoda();}});$('refresh').addEventListener('click',()=>reload());

function fireAge(item){const minutes=Number(item.age_minutes);if(!Number.isFinite(minutes))return 'Nie podano';if(minutes<60)return `${Math.floor(Math.max(0,minutes))} min`;if(minutes<1440)return `${Math.floor(minutes/60)} godz. ${Math.floor(minutes%60)} min`;return `${Math.floor(minutes/1440)} dni ${Math.floor(minutes%1440/60)} godz.`;}
function renderFireStatus(){const status=$('fires-status');status.classList.toggle('notice',Boolean(state.fireError));if(!$('fires-enabled').checked){status.textContent='Warstwa wyłączona.';return;}if(state.fireError){status.textContent=`Nie udało się odczytać wykryć: ${state.fireError}. Spróbuj „Odśwież widok”.`;return;}if(!state.fireData)return;const data=state.fireData;const source=state.sources.find(s=>s.id==='firms');const fresh=source?` · odczyt NASA: ${date(source.last_successful_check||source.last_success_at||source.last_checked_at)} · ${sourceSummary(source)}`:'';status.textContent=`${state.fires.length} z ${data.total??state.fires.length} wykryć · obserwacje ${date(data.window_start)} – ${date(data.window_end)}${data.limited?' · limit rekordów; zawęź województwo lub okno':''}${fresh}`;}
function firePopup(item){const popup=el('div',null,'fire-popup');popup.append(el('h3','Satelitarna anomalia cieplna'),descriptionList([['Obserwacja (Polska)',date(item.observed_at)],['Wiek obserwacji',fireAge(item)],['Satelita / instrument',`${item.satellite||'Nie podano'} / ${item.instrument||'VIIRS'}`],['Pewność wykrycia',({l:'Niska',low:'Niska',n:'Nominalna',nominal:'Nominalna',h:'Wysoka',high:'Wysoka'})[item.confidence]||item.confidence||'Nie podano'],['FRP',item.frp===null||item.frp===undefined?'Nie podano':`${item.frp} MW`],['Województwo',item.voivodeship_name],['Współrzędne',`${item.latitude}, ${item.longitude}`]]),el('p','Wykrycie może oznaczać pożar, wypalanie roślinności lub źródło przemysłowe. Piksel VIIRS nominalnie 375 m nie oznacza rozmiaru pożaru.','muted'),sourceLink('https://firms.modaps.eosdis.nasa.gov/','NASA FIRMS'));return popup;}
function renderFires(){if(!state.map||!window.L)return;if(!state.fireLayer)state.fireLayer=L.layerGroup();state.fireLayer.clearLayers();if(!$('fires-enabled').checked){if(state.map.hasLayer(state.fireLayer))state.map.removeLayer(state.fireLayer);return;}if(!state.map.hasLayer(state.fireLayer))state.fireLayer.addTo(state.map);for(const item of state.fires){if(window.WiciRegion&&!window.WiciRegion.contains(item.latitude,item.longitude))continue;if(!Number.isFinite(item.latitude)||!Number.isFinite(item.longitude))continue;L.circleMarker([item.latitude,item.longitude],{pane:'fireDetections',radius:5,color:'#973e12',weight:1.5,fillColor:'#f47b23',fillOpacity:.85}).bindPopup(firePopup(item)).bindTooltip(el('span',`NASA FIRMS · ${date(item.observed_at)}`)).addTo(state.fireLayer);}}
async function loadFires(){const request=++state.fireRequest;state.fireError=null;state.fires=[];state.fireData=null;renderFires();if(!$('fires-enabled').checked){renderFireStatus();return;}$('fires-status').classList.remove('notice');$('fires-status').textContent='Wczytywanie wykryć NASA FIRMS…';const params=new URLSearchParams({hours:$('fires-hours').value,date:$('selected-day').value});if($('province').value)params.set('voivodeship',$('province').value);try{const data=await api(`/fires?${params}`);if(request!==state.fireRequest)return;state.fireData=data;state.fires=items(data);renderFires();renderFireStatus();}catch(err){if(request!==state.fireRequest)return;state.fireError=err.message||String(err);renderFireStatus();}}
$('fires-enabled').addEventListener('change',()=>loadFires());$('fires-hours').addEventListener('change',()=>loadFires());

// Forecast days follow the server clock in Poland, independent of publication history.
function effisForecastDay(offset=$('effis-day').value){const d=new Date(`${serverDay()}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+Number(offset||0));return d.toISOString().slice(0,10);}
function updateEffisDays(){for(const option of $('effis-day').options||[]){const name=['Dziś','Jutro','Pojutrze'][Number(option.value)];option.textContent=`${name} · ${effisForecastDay(option.value)}`;}$('effis-day').disabled=state.health.mode==='demo';$('effis-enabled').disabled=state.health.mode==='demo';}
function clearEffis(){if(state.effisLayer&&state.map)state.map.removeLayer(state.effisLayer);state.effisLayer=null;state.effisData=null;$('effis-legend').hidden=true;$('effis-legend-image').replaceChildren();}
async function loadEffis(){const request=++state.effisRequest;clearEffis();const status=$('effis-status');status.classList.remove('notice');if(state.health.mode==='demo'){status.textContent='EFFIS wyłączone w demonstracji; brak pobierania realnej prognozy.';return;}if(!$('effis-enabled').checked){status.textContent='Warstwa EFFIS wyłączona.';return;}if(!state.map||!window.L){status.textContent='Prognoza EFFIS wymaga dostępnej mapy.';return;}const day=effisForecastDay();const current=()=>request===state.effisRequest&&$('effis-enabled').checked&&day===effisForecastDay();const fail=(message)=>{if(!current())return;clearEffis();status.classList.toggle('notice',true);status.textContent=`Prognoza na ${day} niedostępna: ${message}. Spróbuj „Odśwież widok”.`;};status.textContent=`Wczytywanie prognozy na ${day}…`;try{const data=await api(`/effis?${new URLSearchParams({day})}`);if(!current())return;if(!data.available){fail(data.message||'brak danych źródła');return;}if(data.forecast_date!==day){fail('źródło zwróciło inny dzień');return;}if(!String(data.image_url||'').startsWith('/api/effis/')||!String(data.legend_url||'').startsWith('/api/effis/')){fail('nieprawidłowy adres warstwy');return;}state.effisData=data;let mapLoaded=false,legendLoaded=false;const show=()=>{if(!current()||!mapLoaded||!legendLoaded)return;$('effis-legend').hidden=false;status.textContent=`Prognoza na ${data.forecast_date} · pobrano ${date(data.fetched_at)} · model ${data.model||'EFFIS'} · mapa FWI`;};const layer=L.imageOverlay(data.image_url,data.bounds||[[49,14],[55,24.2]],{pane:'effisForecast',opacity:.65,interactive:false,attribution:'EFFIS / Copernicus EMS'});state.effisLayer=layer;layer.on('load',()=>{if(!current()||state.effisLayer!==layer)return;mapLoaded=true;show();});layer.on('error',()=>fail('nie udało się wyświetlić mapy FWI'));const legend=el('img');legend.alt='Oficjalna legenda EFFIS: klasy, kolory i progi indeksu FWI';legend.onload=()=>{if(!current()||state.effisLayer!==layer)return;legendLoaded=true;show();};legend.onerror=()=>fail('nie udało się wyświetlić legendy');$('effis-legend-image').append(legend);legend.src=data.legend_url;layer.addTo(state.map);}catch(err){fail(err.message||String(err));}}
$('effis-enabled').addEventListener('change',()=>loadEffis());$('effis-day').addEventListener('change',()=>loadEffis());

// Traffic always shows the current flow, independent of publication filters.
const TRAFFIC_REFRESH_MS=300000;
function trafficVisible(){return $('traffic-enabled').checked&&state.view==='situation'&&!document.hidden&&state.health.mode!=='demo';}
function clearTraffic(){clearRoadPopup();if(state.trafficLayer&&state.map)state.map.removeLayer(state.trafficLayer);state.trafficLayer=null;$('traffic-legend').hidden=true;}
function clearRoadPopup(){state.roadRequest++;const popup=state.roadPopup;state.roadPopup=null;if(popup&&state.map)state.map.closePopup(popup);}
async function lookupTrafficRoad(event){
 if(!trafficVisible()||!state.trafficLayer||!state.map)return;
 if(event.originalEvent?.target?.closest?.('.leaflet-marker-icon,.leaflet-popup,.leaflet-control'))return;
 const point=event.latlng;if(!point||!Number.isFinite(point.lat)||!Number.isFinite(point.lng)||window.WiciRegion&&!window.WiciRegion.contains(point.lat,point.lng))return;
 clearRoadPopup();const request=++state.roadRequest;
 const content=el('div',null,'road-popup');content.append(el('strong','Sprawdzanie drogi…'));
 const popup=L.popup({maxWidth:300}).setLatLng(point).setContent(content);state.roadPopup=popup;
 popup.on('remove',()=>{if(state.roadPopup===popup){state.roadPopup=null;state.roadRequest++;}});popup.openOn(state.map);
 const current=()=>request===state.roadRequest&&state.roadPopup===popup&&trafficVisible()&&state.trafficLayer;
 try{
  const data=await api(`/traffic/road?lat=${point.lat.toFixed(6)}&lon=${point.lng.toFixed(6)}`);if(!current())return;
  clear(content);
  if(data.found){
   content.append(el('strong',data.name||'Droga bez nazwy w źródle'));
   const symbols=el('div',null,'road-symbols');for(const symbol of data.symbols||[])symbols.append(el('span',symbol,'road-symbol'));content.append(symbols);
   if(!data.symbols?.length)content.append(el('p','Źródło nie podało numeru ani symbolu drogi.'));
   content.append(el('small','Droga najbliżej kliknięcia (do 250 m). Przy równoległych drogach przybliż mapę. · Źródło: TomTom'));
  }else content.append(el('strong','Nie znaleziono drogi przy kliknięciu.'),el('p','Przybliż mapę i kliknij dokładniej w drogę.'));
  popup.setContent(content);
 }catch(err){if(current()){clear(content);content.append(el('strong','Nie można odczytać drogi.'),el('p',err.message||'Spróbuj ponownie później.'));popup.setContent(content);}}
}
function armTrafficRefresh(){if(state.trafficTimer!==null)clearInterval(state.trafficTimer);state.trafficTimer=setInterval(()=>loadTraffic(true),TRAFFIC_REFRESH_MS);}
function trafficStatus(message){const data=state.trafficData;const quota=data?` · kafelki w ${data.month||'bieżącym miesiącu'}: ${data.requests_used??0} / ${data.monthly_limit??190000}`:'';const fetched=data?.last_fetch_at?` · ostatnie lokalne pobranie: ${date(data.last_fetch_at)} (nie czas zdarzenia)`:'';$('traffic-status').textContent=message+quota+fetched;}
async function loadTraffic(refresh=true){
 const request=++state.trafficRequest;
 if(!trafficVisible()){clearTraffic();trafficStatus(state.health.mode==='demo'?'TomTom wyłączone w demonstracji.':$('traffic-enabled').checked?'Pobieranie wstrzymane poza widoczną mapą.':'Warstwa TomTom wyłączona.');return;}
 if(Date.now()<state.trafficRetryAt)return;
 const current=()=>request===state.trafficRequest&&trafficVisible();
 const fail=()=>{if(!current())return;state.trafficRetryAt=Date.now()+TRAFFIC_REFRESH_MS;armTrafficRefresh();clearTraffic();$('traffic-status').classList.toggle('notice',true);trafficStatus('Ruch TomTom niedostępny. Ponowna próba przy następnym odświeżeniu (za około 5 min).');};
 try{
  const data=await api('/traffic');if(!current())return;state.trafficData=data;
  if(!data.enabled||['disabled','error','limit'].includes(data.status)){clearTraffic();trafficStatus(data.message||'Ruch TomTom niedostępny.');return;}
  if(data.tile_url!=='/api/traffic/tiles/{z}/{x}/{y}.png'){fail();return;}
  if(!state.map||!window.L){trafficStatus('Ruch TomTom wymaga dostępnej mapy.');return;}
  $('traffic-status').classList.remove('notice');
  if(state.trafficLayer){if(refresh)state.trafficLayer.redraw();trafficStatus(state.trafficLayer.trafficLoadedTiles?'Aktualny ruch TomTom · odświeżanie co 5 min.':'Brak kafelków ruchu w widocznym obszarze. Przybliż mapę Polski (zoom 6–18).');return;}
  const layer=L.tileLayer(data.tile_url,{pane:'trafficFlow',tileSize:256,bounds:[[49,14],[55,24.2]],noWrap:true,keepBuffer:0,updateWhenIdle:true,updateWhenZooming:false,minZoom:6,maxNativeZoom:18,maxZoom:18,attribution:'&copy; <a href="https://www.tomtom.com/copyright/" target="_blank" rel="noopener noreferrer">TomTom</a>'});
  state.trafficLayer=layer;layer.trafficLoadedTiles=0;let tileBatch=0,metadataBatch=-1;
  layer.on('loading',()=>{layer.trafficLoadedTiles=0;tileBatch++;});
  layer.on('tileload',()=>{if(state.trafficLayer===layer)layer.trafficLoadedTiles++;});
  layer.on('tileerror',()=>{if(state.trafficLayer!==layer||!trafficVisible())return;state.trafficRequest++;state.trafficRetryAt=Date.now()+TRAFFIC_REFRESH_MS;armTrafficRefresh();clearTraffic();$('traffic-status').classList.toggle('notice',true);trafficStatus('Ruch TomTom niedostępny. Ponowna próba przy następnym odświeżeniu (za około 5 min).');});
  layer.on('load',async()=>{
   if(state.trafficLayer!==layer||!trafficVisible())return;
   $('traffic-legend').hidden=layer.trafficLoadedTiles===0;
   const message=layer.trafficLoadedTiles?'Aktualny ruch TomTom · odświeżanie co 5 min.':'Brak kafelków ruchu w widocznym obszarze. Przybliż mapę Polski (zoom 6–18).';trafficStatus(message);
   if(!layer.trafficLoadedTiles||metadataBatch===tileBatch)return;
   metadataBatch=tileBatch;const batch=tileBatch,metadataRequest=state.trafficRequest;
   const active=()=>state.trafficLayer===layer&&trafficVisible()&&tileBatch===batch&&state.trafficRequest===metadataRequest;
   try{const updated=await api('/traffic');if(!active())return;state.trafficData=updated;if(!updated.enabled||['disabled','error','limit'].includes(updated.status)){clearTraffic();trafficStatus(updated.message||'Ruch TomTom niedostępny.');return;}trafficStatus(message);}
   catch{if(active())trafficStatus('Nie udało się odświeżyć stanu użycia TomTom; poniżej ostatni odczyt.');}
  });
  trafficStatus('Wczytywanie aktualnego ruchu TomTom…');layer.addTo(state.map);
 }catch{fail();}
}
function syncTraffic(refresh=true){
 if(!trafficVisible()){
  if(state.trafficTimer!==null){clearInterval(state.trafficTimer);state.trafficTimer=null;}
  return loadTraffic(refresh);
 }
 if(state.trafficTimer===null)armTrafficRefresh();
 return loadTraffic(refresh);
}
$('traffic-enabled').addEventListener('change',()=>syncTraffic());
document.addEventListener?.('visibilitychange',()=>{const traffic=syncTraffic();syncGddkia();syncOsm();syncWeather();return traffic;});

document.addEventListener?.('wici:regionchange',()=>{renderFires();renderGddkia();if(state.gddkiaData)renderGddkiaStatus();});
// GDDKiA reports road restrictions separately from TomTom flow and publication history.
const GDDKIA_REFRESH_MS=300000;
function gddkiaVisible(){return $('gddkia-enabled').checked&&state.view==='situation'&&!document.hidden&&state.health.mode!=='demo';}
function clearGddkia(){if(state.gddkiaLayer&&state.map)state.map.removeLayer(state.gddkiaLayer);state.gddkiaLayer=null;}
function gddkiaPopup(item){
 const popup=el('div',null,'gddkia-popup');
 popup.append(el('h3',`Utrudnienie GDDKiA · ${item.road||'Nie podano'}`));
 if(state.gddkiaData?.stale||state.gddkiaData?.status==='error')popup.append(el('p','Nieaktualny odczyt; aktualność utrudnienia niepotwierdzona.','notice'));
 if(item.upcoming)popup.append(el('p','Utrudnienie zapowiedziane.','muted'));
 if(item.planned_end_passed)popup.append(el('p','Planowany koniec minął; nadal w zestawieniu GDDKiA','notice'));
 popup.append(descriptionList([['Droga',item.road||'Nie podano'],['Odcinek',item.section||'Nie podano'],['Województwo',item.province||'Nie podano'],['Przyczyna',item.cause||'Nie podano'],['Skutki według źródła',Array.isArray(item.effects)&&item.effects.length?item.effects.join('; '):'Nie podano'],['Początek',date(item.start_at)],['Planowany koniec',date(item.planned_end_at)],['Opis / objazd',item.description||'Nie podano']]),el('p','Punkt wskazuje środek odcinka objętego utrudnieniem, nie dokładne miejsce kolizji. Planowany koniec nie potwierdza usunięcia utrudnienia.','muted'),sourceLink(item.source_url||state.gddkiaData?.source_url,'GDDKiA · źródło XML'));
 return popup;
}
function renderGddkia(){
 clearGddkia();if(!gddkiaVisible()||!state.map||!window.L||!state.gddkiaData?.enabled)return;
 const group=L.layerGroup();state.gddkiaLayer=group;
 const points=new Map();for(const item of state.gddkiaData.items||[]){if(window.WiciRegion&&!window.WiciRegion.contains(item.latitude,item.longitude))continue;if(!Number.isFinite(item.latitude)||!Number.isFinite(item.longitude))continue;const key=`${item.latitude},${item.longitude}`;if(!points.has(key))points.set(key,[]);points.get(key).push(item);}
 for(const entries of points.values()){const item=entries[0],popup=el('div');for(const entry of entries)popup.append(gddkiaPopup(entry));
  L.circleMarker([item.latitude,item.longitude],{pane:'gddkiaIncidents',radius:6,color:'#542b82',weight:2,fillColor:'#9a60c7',fillOpacity:.85,bubblingMouseEvents:false}).bindPopup(popup,{maxHeight:340,maxWidth:340}).bindTooltip(el('span',`GDDKiA · ${item.road||'Nie podano'} · ${entries.length} ${entries.length===1?'utrudnienie':'utrudnienia'}`)).addTo(group);
 }
 group.addTo(state.map);
}
function renderGddkiaStatus(message){
 const data=state.gddkiaData,status=$('gddkia-status');
 const stale=Boolean(data?.stale||data?.status==='error');status.classList.toggle('notice',stale||data?.status==='partial');
 if(message){status.textContent=message;return;}
 if(!data){status.textContent='Wczytywanie utrudnień GDDKiA…';return;}
 if(!data.enabled){status.textContent=data.message||'Utrudnienia GDDKiA niedostępne.';return;}
 status.textContent=`${stale?'Nieaktualny odczyt GDDKiA; aktualność utrudnień niepotwierdzona. ':''}${data.message?data.message+' · ':''}${new Set((data.items||[]).filter(item=>Number.isFinite(item.latitude)&&Number.isFinite(item.longitude)).map(item=>`${item.latitude},${item.longitude}`)).size} punktów · ${data.items?.length||0} zlokalizowanych utrudnień · ${data.total??0} utrudnień w zestawieniu · bez współrzędnych: ${data.unmapped_count??0} · pominięte nieprawidłowe: ${data.invalid_count??0} · wygenerowano u źródła: ${date(data.source_generated_at)} · ostatni poprawny lokalny odczyt: ${date(data.last_success_at)} · ostatnia próba: ${date(data.last_attempt_at)}`;
}
async function loadGddkia(){
 const request=++state.gddkiaRequest;
 if(!gddkiaVisible()){clearGddkia();renderGddkiaStatus(state.health.mode==='demo'?'GDDKiA wyłączone w demonstracji.':$('gddkia-enabled').checked?'Pobieranie GDDKiA wstrzymane poza widoczną mapą.':'Warstwa GDDKiA wyłączona.');return;}
 const current=()=>request===state.gddkiaRequest&&gddkiaVisible();
 if(!state.gddkiaData)renderGddkiaStatus();
 try{const data=await api('/gddkia');if(!current())return;state.gddkiaData=data;renderGddkia();renderGddkiaStatus();}
 catch{if(!current())return;if(state.gddkiaData?.enabled){state.gddkiaData={...state.gddkiaData,stale:true,status:'error',message:'Nie udało się pobrać GDDKiA; zachowano ostatnie dane.'};renderGddkia();renderGddkiaStatus();}else renderGddkiaStatus('Nie udało się pobrać utrudnień GDDKiA. Ponowna próba za 5 minut.');}
}
function syncGddkia(refresh=true){
 if(!gddkiaVisible()){if(state.gddkiaTimer!==null){clearInterval(state.gddkiaTimer);state.gddkiaTimer=null;}return loadGddkia();}
 if(state.gddkiaTimer===null)state.gddkiaTimer=setInterval(()=>loadGddkia(),GDDKIA_REFRESH_MS);
 if(refresh||!state.gddkiaLayer)return loadGddkia();
}
$('gddkia-enabled').addEventListener('change',()=>syncGddkia());

// Browser-managed OSM base tiles: visible map only, without scheduled redraws.
function osmVisible(){return $('osm-enabled').checked&&state.health.mode==='live'&&state.view==='situation'&&!document.hidden&&Boolean(state.map)&&Boolean(window.L);}
function osmStatus(message){$('osm-status').classList.toggle('notice',state.osmError);$('osm-status').textContent=message;}
function syncOsm(){
 $('osm-enabled').disabled=state.health.mode!=='live';
 const visible=osmVisible();
 state.administrativeLayer?.setStyle({fillOpacity:visible?0:1});
 if(state.administrativeLayer)$('map-note').textContent=visible?'Podkład drogowy OpenStreetMap · granice administracyjne PRG / GUGiK. Rekordy bez geometrii pozostają na liście.':'Lokalne granice administracyjne PRG / GUGiK. Rekordy bez geometrii pozostają na liście.';
 if(!visible){if(state.osmLayer&&state.map?.hasLayer(state.osmLayer))state.map.removeLayer(state.osmLayer);state.osmError=false;osmStatus(state.health.mode==='demo'?'Podkład OpenStreetMap wyłączony w demonstracji.':state.health.mode!=='live'?'Podkład OpenStreetMap oczekuje na sprawdzenie trybu aplikacji.':!$('osm-enabled').checked?'Podkład OpenStreetMap wyłączony.':'Podkład OpenStreetMap wstrzymany poza widoczną mapą.');return;}
 if(!state.osmLayer){
  const layer=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{pane:'osmBase',tileSize:256,maxNativeZoom:19,maxZoom:19,noWrap:true,keepBuffer:0,updateWhenIdle:true,updateWhenZooming:false,referrerPolicy:'strict-origin-when-cross-origin',attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap contributors</a>'});
  state.osmLayer=layer;
  const active=()=>state.osmLayer===layer&&osmVisible()&&state.map.hasLayer(layer);
  layer.on('loading',()=>{if(!active())return;state.osmError=false;osmStatus('Wczytywanie podkładu OpenStreetMap…');});
  layer.on('tileerror',()=>{if(!active())return;state.osmError=true;osmStatus('Podkład OSM niedostępny; granice i znaczniki pozostają dostępne');});
  layer.on('load',()=>{if(!active()||state.osmError)return;osmStatus('Podkład drogowy OpenStreetMap.');});
 }
 if(!state.map.hasLayer(state.osmLayer)){osmStatus('Wczytywanie podkładu OpenStreetMap…');state.osmLayer.addTo(state.map);}
}
$('osm-enabled').addEventListener('change',()=>syncOsm());

let loading=false;
async function reload(){
 if(loading)return;loading=true;$('refresh').disabled=true;
 try{
  await loadHealth();
  const mapInit=initMap(),afterMap=mapInit.catch(()=>{});
  const results=await Promise.allSettled([
   loadSources(),afterMap.then(()=>loadCommunications()),
   mapInit.then(()=>{syncTraffic(false);syncGddkia(false);syncWeather();return loadEffis();}),
   afterMap.then(()=>loadFires())
  ]);
  for(const result of results)if(result.status==='rejected')error(result.reason);
  if(results.every(result=>result.status==='fulfilled'))$('global-status').textContent='';
 }catch(err){error(err);}finally{loading=false;$('refresh').disabled=false;}
}
const notices=el('a','Oznaczenia i warunki dostawców danych');notices.href='/notices';document.querySelector('footer').append(el('br'),notices);
reload();setInterval(reload,60000);

function renderCommunications(){const root=$('communication-list');clear(root);if(!state.communications.length){root.append(el('p','Brak zapisanych komunikatów dla wybranego dnia.','empty'));return;}for(const source of ['imgw_meteo','rso','rcb','sg']){const set=state.communications.filter(e=>e.source_id===source);if(!set.length)continue;root.append(el('div',`${set[0].source_name} · ${set.length}`,'group-heading'));for(const bundle of compactGroups(set)){let target=root;if(bundle.length>1){const group=el('details',null,'compact-group');group.open=bundle.some(item=>item.id===state.selected);group.append(el('summary',`${bundle[0].title.split(' — ')[0]} · ${bundle.length} obszarów · wspólny komunikat IMGW`));root.append(group);target=group;}for(const item of bundle){const b=el('button',null,`record${state.selected===item.id?' active':''}`);b.type='button';b.setAttribute('data-communication-id',item.id);b.setAttribute('aria-pressed',String(state.selected===item.id));const badges=el('div',null,'badges');badges.append(badge(item.communication_type==='exercise'?'Ćwiczenie':item.communication_type==='warning'?'Ostrzeżenie IMGW':'Oficjalny komunikat'));if(item.official_severity)badges.append(badge(`Stopień ${item.official_severity}`,`severity-${item.official_severity}`));if(item.communication_type==='warning')badges.append(badge(item.warning_status));if(item.redacted)badges.append(badge('Treść zminimalizowana'));if(item.selection_basis==='display_window')badges.append(badge('Udostępniany dziś w RSO'));if(item.selection_basis==='source_updated_at')badges.append(badge('Aktualizacja w wybranym dniu'));b.append(badges,el('h3',item.title),el('p',locationText(item)),el('small',`Publikacja: ${item.publication_day} · wersja ${item.version_number}${item.source_updated_at?' · aktualizacja '+date(item.source_updated_at):''}`));b.addEventListener('click',()=>selectCommunication(item.id));target.append(b);}}}}
function renderCommunication(item){const root=$('details');clear(root);root.append(el('div',`${item.source_name} · automatyczny odczyt komunikatu`,'eyebrow'),el('h2',item.title),el('div',item.summary||'Wydawca nie udostępnił treści tekstowej.','document-text'),sourceLink(item.original_url||item.url,'Otwórz oryginał'));root.append(descriptionList([['Publikacja źródła',publishedTime(item)],['Aktualizacja źródła',date(item.source_updated_at)],['Pierwszy lokalny odczyt',date(item.first_seen_at)],['Ostatni odczyt',date(item.last_checked_at)],['Obszary',locationText(item)]]));if(item.publication_day_basis==='first_seen_at')root.append(el('p','Dzień wynika z pierwszego lokalnego odczytu; źródło nie podało daty.','notice'));if(item.redacted)root.append(el('p',item.redaction_note||'Treść zminimalizowana przed zapisem; sprawdź oryginał.','notice'));if(item.communication_type==='exercise')root.append(el('p','Ćwiczenie / test według komunikatu, nie rzeczywisty alarm.','notice'));if(item.source_id==='imgw_meteo'){root.append(descriptionList([['Stopień IMGW',item.official_severity||'Nie podano'],['Ważność od',date(item.valid_from)],['Ważność do',date(item.valid_until)],['Status',label(item.warning_status)]]),imgwNotice());}if(item.display_window){root.append(descriptionList([['Okno publikacji RSO od',date(item.display_window.valid_from)],['Okno publikacji RSO do',date(item.display_window.valid_until)]]),el('p','Okno RSO opisuje udostępnianie komunikatu, nie czas trwania zagrożenia.','muted'));}root.append(el('p',item.map_note,'muted'));const history=section(root,'Zapisane wersje komunikatu');for(const version of item.history||[]){const d=el('details');d.append(el('summary',`Wersja ${version.version_number} · odczyt ${date(version.created_at)}`),el('strong',version.title),el('p',version.text),sourceLink(version.original_url,'Oryginał tej wersji'));history.append(d);}}
function renderProvinceCards(){const groups=new Map();for(const item of state.communications){const codes=new Set(locations(item).map(l=>l.admin_code?.slice(0,2)).filter(Boolean));for(const code of codes){if(!groups.has(code))groups.set(code,[]);groups.get(code).push(item);}}for(const [code,entries] of groups){const geo=state.geometries.get(code);if(!geo)continue;const center=L.geoJSON(geo).getBounds().getCenter();const card=el('button',null,'province-card');card.type='button';card.append(el('strong',`${geo.properties.name} · ${entries.length}`),el('span',entries[0].title.length>52?entries[0].title.slice(0,52)+'…':entries[0].title));card.setAttribute('aria-label',`${geo.properties.name}: ${entries.length} komunikatów. Otwórz listę.`);const marker=L.marker(center,{icon:L.divIcon({className:'province-card-anchor',html:card,iconSize:[160,48],iconAnchor:[80,24]}),keyboard:true});const popup=el('div',null,'map-popup');popup.append(el('strong',geo.properties.name),el('p','Komunikaty obszaru; punkt karteczki nie oznacza miejsca zdarzenia.'));for(const item of entries){const button=el('button',`${item.source_name}: ${item.title}`);button.addEventListener('click',()=>selectCommunication(item.id));popup.append(button);}marker.bindPopup(popup).addTo(state.map);state.cards.push(marker);}}
async function selectCommunication(id){state.selected=id;const detailRevision=window.WiciAtlas?.revision;renderCommunications();try{const item=await api(`/communications/${encodeURIComponent(id)}`);if(state.selected!==id)return;renderCommunication(item);window.WiciIoda?.showCommunications();if(detailRevision===window.WiciAtlas?.revision)window.WiciAtlas?.openDetails(id);highlightMap(id);}catch(err){if(state.selected===id)error(err);}}

function syncIoda(){window.WiciPositionQuality?.sync({map:state.map,api,day:state.day,province:$('province').value,visible:state.view==='situation'&&!document.hidden});window.WiciIoda?.sync({map:state.map,geometries:state.geometries,api,day:state.day,province:$('province').value,now:state.health.now,visible:state.view==='situation'&&!document.hidden});}
function syncWeather(){if(window.WiciRegion&&!window.WiciRegion.ready())return;syncIoda();if(!state.map)return;window.WiciSentinel5P?.init({map:state.map,visible:state.view==='situation'&&!document.hidden});window.WiciSentinel5P?.sync({visible:state.view==='situation'&&!document.hidden});window.WiciSentinel2?.init({map:state.map});window.WiciSentinel2?.sync({visible:state.view==='situation'&&!document.hidden});window.WiciGios?.init({map:state.map,api,visible:state.view==='situation'&&!document.hidden});window.WiciGios?.sync({visible:state.view==='situation'&&!document.hidden});window.WiciGFM?.init({map:state.map,api,visible:state.view==='situation'&&!document.hidden});window.WiciGFM?.sync({visible:state.view==='situation'&&!document.hidden});window.WiciHydro?.init({map:state.map,api,visible:state.view==='situation'&&!document.hidden});window.WiciHydro?.sync({visible:state.view==='situation'&&!document.hidden});window.WiciImagery?.init({map:state.map,api,visible:state.view==='situation'&&!document.hidden});window.WiciImagery?.sync({visible:state.view==='situation'&&!document.hidden});window.WiciBuses?.init({map:state.map,health:state.health});window.WiciBuses?.sync({visible:state.view==='situation'&&!document.hidden,health:state.health});window.WiciTracking?.init({map:state.map,health:state.health});window.WiciTracking?.sync({visible:state.view==='situation'&&!document.hidden,health:state.health});window.WiciAircraft?.init({map:state.map,api,health:state.health});window.WiciAircraft?.sync({visible:state.view==='situation'&&!document.hidden,health:state.health});window.WiciTrains?.init({map:state.map,health:state.health});window.WiciTrains?.sync({visible:state.view==='situation'&&!document.hidden,health:state.health});window.WiciShips?.init({map:state.map,health:state.health});window.WiciShips?.sync({visible:state.view==='situation'&&!document.hidden,health:state.health});window.WiciUkraine?.init({map:state.map,api,health:state.health,visible:state.view==='situation'&&!document.hidden});window.WiciUkraine?.sync({health:state.health,visible:state.view==='situation'&&!document.hidden});window.WiciLightning?.init({map:state.map,api,visible:state.view==='situation'&&!document.hidden});window.WiciLightning?.sync({visible:state.view==='situation'&&!document.hidden});window.WiciRadar?.init({map:state.map,api,visible:state.view==='situation'&&!document.hidden});window.WiciRadar?.sync({visible:state.view==='situation'&&!document.hidden});window.WiciLayers?.update();if(!window.WiciWeather)return;window.WiciWeather.init({map:state.map,api,date,health:state.health});window.WiciWeather.sync({visible:state.view==='situation'&&!document.hidden,health:state.health});}
